632							<div class="field">
633								<label for="email">Email <span class="form-hint" aria-hidden="true">(required)</span></label>
634								<input type="email" id="email" name="email" autocomplete="email" inputmode="email" spellcheck="false" autocapitalize="none" required aria-describedby="email-help email-error">
635								<span id="email-error" class="error-message" aria-live="polite"></span>
