734			const themeToggle = document.getElementById('theme-toggle');
735			const htmlElement = document.documentElement;
736			const prefersDark = window.matchMedia('(prefers-color-scheme: dark)');
737	
738			const themeColors = { light: '#ffffff', dark: '#121212' };
739			const themeColorMetas = document.querySelectorAll('meta[name="theme-color"]');
740			themeColorMetas.forEach((meta) => {
741				meta.dataset.defaultContent = meta.content;
742			});
743	
744			const updateThemeUI = () => {
745				const forced = htmlElement.dataset.theme;
746				const isDark = forced ? forced === 'dark' : prefersDark.matches;
747				const label = isDark ? 'Switch to light mode' : 'Switch to dark mode';
748				themeToggle.textContent = isDark ? '☀️' : '🌙';
749				themeToggle.setAttribute('aria-label', label);
750				themeToggle.title = label;
751				themeColorMetas.forEach((meta) => {
752					meta.content = forced ? themeColors[forced] : meta.dataset.defaultContent;
753				});
754			};
755	
756			if (themeToggle) {
757				themeToggle.hidden = false;
758				updateThemeUI();
759	
760				themeToggle.addEventListener('click', () => {
761					const systemTheme = prefersDark.matches ? 'dark' : 'light';
762					const current = htmlElement.dataset.theme || systemTheme;
763					const next = current === 'dark' ? 'light' : 'dark';
764					// Choosing the system theme clears the override so the page follows the OS again.
765					try {
766						if (next === systemTheme) {
767							delete htmlElement.dataset.theme;
768							localStorage.removeItem('theme');
769						} else {
770							htmlElement.dataset.theme = next;
771							localStorage.setItem('theme', next);
772						}
773					} catch {}
774					updateThemeUI();
775				});
776	
777				prefersDark.addEventListener('change', () => {
778					if (!htmlElement.dataset.theme) {
779						updateThemeUI();
780					}
781				});
782	
783				// Keep other open tabs in step with the choice made in this one.
784				window.addEventListener('storage', (event) => {
785					if (event.key !== null && event.key !== 'theme') {
786						return;
787					}
788					if (event.newValue === 'light' || event.newValue === 'dark') {
789						htmlElement.dataset.theme = event.newValue;
790					} else {
791						delete htmlElement.dataset.theme;
792					}
793					updateThemeUI();
794				});
795			}
796	
797			const copyrightYear = document.getElementById('copyright-year');
798			if (copyrightYear) {
799				copyrightYear.textContent = String(new Date().getFullYear());
800			}
801	
802			const messages = [
803				"This update was announced to screen readers!",
804				"Dynamic content updates work with aria-live regions.",
805				"Live regions are essential for accessible web apps.",
806				"Try this with a screen reader like NVDA or JAWS!"
807			];
808			let nextMessage = 0;
809			let count = 0;
810			const announceBtn = document.getElementById('announce');
811			const liveMessage = document.getElementById('live-message');
812			const contactForm = document.getElementById('contact-form');
813			const emailInput = document.getElementById('email');
814			const messageInput = document.getElementById('message');
815			const messageCount = document.getElementById('message-count');
816			const messageCountStatus = document.getElementById('message-count-status');
817			const formStatus = document.getElementById('form-status');
818			const countDisplay = document.getElementById('count');
819			const countMessage = document.getElementById('count-message');
820			const decreaseBtn = document.getElementById('decrease');
821			const increaseBtn = document.getElementById('increase');
822			const resetBtn = document.getElementById('reset');
823	
824			const updateCountDisplay = () => {
825				countDisplay.textContent = String(count);
826				countMessage.textContent = `Count is ${count}.`;
827			};
828	
829			if (countDisplay && countMessage) {
830				decreaseBtn?.addEventListener('click', () => {
831					count--;
832					updateCountDisplay();
833				});
834	
835				increaseBtn?.addEventListener('click', () => {
836					count++;
837					updateCountDisplay();
838				});
839	
840				resetBtn?.addEventListener('click', () => {
841					count = 0;
842					updateCountDisplay();
843				});
844			}
845	
846			if (announceBtn && liveMessage) {
847				announceBtn.addEventListener('click', () => {
848					liveMessage.textContent = messages[nextMessage];
849					nextMessage = (nextMessage + 1) % messages.length;
850				});
851			}
852	
853			if (contactForm) {
854				const emailError = document.getElementById('email-error');
855				const submitBtn = contactForm.querySelector('button[type="submit"]');
856				const isSending = () => submitBtn.getAttribute('aria-disabled') === 'true';
857	
858				// Set here rather than in the markup so native validation still works without JavaScript.
859				contactForm.noValidate = true;
860	
861				const setFormStatus = (message, state) => {
862					formStatus.textContent = message;
863					if (state) {
864						formStatus.dataset.state = state;
865					} else {
866						delete formStatus.dataset.state;
867					}
868				};
869	
870				const countThresholds = [0, 10, 25, 50, 100];
871				let lastThreshold;
872	
873				const updateMessageCount = () => {
874					if (messageInput && messageCount) {
875						const remaining = messageInput.maxLength - messageInput.value.length;
876						// Match the page language rather than the browser locale.
877						messageCount.textContent = remaining.toLocaleString(htmlElement.lang);
878						// Announce only when a threshold is crossed, not on every keystroke.
879						const threshold = countThresholds.find((limit) => remaining <= limit);
880						if (messageCountStatus && threshold !== lastThreshold) {
881							lastThreshold = threshold;
882							messageCountStatus.textContent = threshold === undefined
883								? ''
884								: `${remaining.toLocaleString(htmlElement.lang)} characters remaining.`;
885						}
886					}
887				};
888	
889				messageInput?.addEventListener('input', updateMessageCount);
890				// Browsers may restore field values on back/forward navigation.
891				window.addEventListener('pageshow', updateMessageCount);
892				updateMessageCount();
893	
894				const setEmailError = (message) => {
895					emailError.textContent = message;
896					if (message) {
897						emailInput.setAttribute('aria-invalid', 'true');
898						emailInput.setAttribute('aria-describedby', 'email-error email-help');
899					} else {
900						emailInput.removeAttribute('aria-invalid');
901						emailInput.setAttribute('aria-describedby', 'email-help');
902					}
903				};
904	
905				const validateEmail = () => {
906					let message = '';
907					if (emailInput.validity.valueMissing) {
908						message = 'Email address is required.';
909					} else if (emailInput.validity.typeMismatch) {
910						message = 'Please enter a valid email address (e.g., name@example.com).';
911					} else if (!emailInput.validity.valid) {
912						message = 'Please enter a valid email address.';
913					}
914					setEmailError(message);
915					return !message;
916				};
917	
918				emailInput.addEventListener('blur', () => {
919					if (emailInput.value || emailInput.hasAttribute('aria-invalid')) {
920						validateEmail();
921					}
922				});
923	
924				emailInput.addEventListener('input', () => {
925					if (emailInput.hasAttribute('aria-invalid')) {
926						validateEmail();
927					}
928				});
929	
930				contactForm.addEventListener('input', () => {
931					if (!isSending()) {
932						setFormStatus('');
933					}
934				});
935	
936				contactForm.addEventListener('submit', async (event) => {
937					event.preventDefault();
938					if (isSending()) {
939						return;
940					}
941					setFormStatus('');
942					if (!validateEmail()) {
943						setFormStatus('Please correct the errors above before submitting.', 'error');
944						emailInput.focus();
945						return;
946					}
947					const originalText = submitBtn.textContent;
948					submitBtn.setAttribute('aria-disabled', 'true');
949					submitBtn.setAttribute('aria-busy', 'true');
950					submitBtn.textContent = 'Sending…';
951					setFormStatus('Sending your message…', 'pending');
952					emailInput.readOnly = true;
953					if (messageInput) messageInput.readOnly = true;
954					await new Promise(resolve => setTimeout(resolve, 800));
955					emailInput.readOnly = false;
956					if (messageInput) messageInput.readOnly = false;
957					contactForm.reset();
958					setEmailError('');
959					updateMessageCount();
960					submitBtn.removeAttribute('aria-disabled');
961					submitBtn.removeAttribute('aria-busy');
962					submitBtn.textContent = originalText;
963					setFormStatus('Success! Thanks for your message. This is a demo, so nothing was sent.');
964					emailInput.focus();
965				});
966			}
